def get_duration(priority: int) -> int:
  return {1: 60, 2: 40, 3: 20, 4: 10, 5: 5}[int(priority)]


def env_bool(name: str, default: bool = False) -> bool:
    raw = os.getenv(name)
    if raw is None:
        return default
    return raw.strip().lower() in {"1", "true", "yes", "y", "on"}


def load_env_file() -> None:
    candidates = [
        Path.cwd() / ".env",
        Path(__file__).resolve().parents[3] / ".env",
    ]
    loaded_path = None
    for path in candidates:
        if path.exists():
            loaded_path = path
            break

    if loaded_path is None:
        print("No .env file found; using existing environment variables only.")
        return

    for line in loaded_path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        value = value.strip().strip("'\"")
        # Keep explicit shell env values if already provided.
        if key and key not in os.environ:
            os.environ[key] = value

    print(f"Loaded environment variables from {loaded_path}")


def connect_target():
    required = ["DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASSWORD"]
    missing = [key for key in required if not os.getenv(key)]
    if missing:
        raise RuntimeError(f"Missing required environment variables: {', '.join(missing)}")

    return psycopg2.connect(
        host=os.environ["DB_HOST"],
        port=os.environ["DB_PORT"],
        dbname=os.environ["DB_NAME"],
        user=os.environ["DB_USER"],
        password=os.environ["DB_PASSWORD"],
    )


def table_columns(cur, table: str) -> list[str]:
    schema, table_name = table.split(".", 1)
    cur.execute(
        """
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema = %s AND table_name = %s
        ORDER BY ordinal_position
        """,
        (schema, table_name),
    )
    return [r[0] for r in cur.fetchall()]


def insert_rows(cur, table: str, rows: list[dict[str, Any]], dry_run: bool) -> None:
    if not rows:
        print(f"[SKIP] {table}: 0 rows")
        return

    columns = table_columns(cur, table)
    row_values = [tuple(row.get(col) for col in columns) for row in rows]
    column_sql = ", ".join(columns)
    sql = f"INSERT INTO {table} ({column_sql}) VALUES %s ON CONFLICT DO NOTHING"
    if dry_run:
        print(f"[DRY_RUN] {table}: would insert {len(row_values)} rows if missing")
        return
    try:
        execute_values(cur, sql, row_values, page_size=500)
    except Exception as exc:
        raise RuntimeError(f"Failed inserting into {table}: {exc}") from exc
    print(f"[INSERT_IF_MISSING] {table}: attempted {len(row_values)} rows")


def insert_public_patients_if_missing(cur, dry_run: bool) -> None:
    if not PUBLIC_PATIENT_ROWS:
        print("[SKIP] public.patients: 0 rows")
        return

    sql = """
    INSERT INTO public.patients (
      patient_id,
      full_name,
      email,
      email_verified,
      is_admin,
      role,
      clinic_id,
      password_hash,
      medical_profile_json,
      professional_profile_json,
      created_at,
      updated_at,
      last_login_at
    )
    VALUES (
      %(patient_id)s,
      %(full_name)s,
      %(email)s,
      %(email_verified)s,
      %(is_admin)s,
      %(role)s,
      %(clinic_id)s,
      %(password_hash)s,
      %(medical_profile_json)s,
      %(professional_profile_json)s,
      %(created_at)s,
      %(updated_at)s,
      %(last_login_at)s
    )
    ON CONFLICT (patient_id) DO NOTHING
    """
    if dry_run:
        print(f"[DRY_RUN] public.patients: would insert {len(PUBLIC_PATIENT_ROWS)} rows if missing")
        return

    for row in PUBLIC_PATIENT_ROWS:
        try:
            cur.execute(sql, row)
        except Exception as exc:
            raise RuntimeError(f"Failed inserting into public.patients: {exc}") from exc
    print(f"[INSERT_IF_MISSING] public.patients: attempted {len(PUBLIC_PATIENT_ROWS)} rows")


def insert_chat_turns_with_cycle_break(cur, dry_run: bool) -> None:
    table = "rag.chat_turns"
    rows = TABLE_DATA.get(table, [])
    if not rows:
        print(f"[SKIP] {table}: 0 rows")
        return

    staged = []
    for row in rows:
        staged_row = dict(row)
        staged_row["trace_id"] = None
        staged_row["run_id"] = None
        staged.append(staged_row)
    insert_rows(cur, table, staged, dry_run=dry_run)


def backfill_chat_turn_trace_run(cur, dry_run: bool) -> None:
    rows = TABLE_DATA.get("rag.chat_turns", [])
    updates = [
        (row.get("trace_id"), row.get("run_id"), row["turn_id"])
        for row in rows
        if row.get("trace_id") is not None or row.get("run_id") is not None
    ]
    if not updates:
        print("[SKIP] rag.chat_turns backfill: 0 rows")
        return
    if dry_run:
        print(f"[DRY_RUN] rag.chat_turns backfill: would update {len(updates)} rows")
        return
    cur.executemany(
        "UPDATE rag.chat_turns SET trace_id = %s, run_id = %s WHERE turn_id = %s",
        updates,
    )
    print(f"[UPDATE] rag.chat_turns backfill: {len(updates)} rows")


def _clinic_name_map(cur) -> dict[str, str]:
    cur.execute("SELECT clinic_id, clinic_name FROM public.clinics")
    clinic_names = {clinic_id: clinic_name for clinic_id, clinic_name in cur.fetchall()}
    if clinic_names:
        return clinic_names

    fallback = {}
    for row in TABLE_DATA.get("rag.clinics", []):
        clinic_id = row.get("clinic_id")
        clinic_name = row.get("clinic_name")
        if clinic_id and clinic_name:
            fallback[clinic_id] = str(clinic_name).removeprefix("Walk-in ").strip()
    return fallback


def _queue_records_from_payload(cur) -> list[dict[str, Any]]:
    clinic_names = _clinic_name_map(cur)
    sessions_by_id = {
        row["session_id"]: row
        for row in TABLE_DATA.get("rag.patient_chat_sessions", [])
        if row.get("patient_id") == PATIENT_ID and row.get("session_id")
    }

    queue_records = []
    for output_row in TABLE_DATA.get("rag.chat_outputs", []):
        session_id = output_row.get("session_id")
        if not session_id:
            continue

        session_row = sessions_by_id.get(session_id)
        if session_row is None:
            continue

        clinic_id = session_row.get("clinic_id")
        clinic_name = clinic_names.get(clinic_id)
        if not clinic_name:
            continue

        priority = URGENCY_TO_PRIORITY.get(str(output_row.get("urgency_band") or "").strip().lower(), 4)
        arrival_time = session_row.get("started_at") or output_row.get("created_at")
        if not arrival_time:
            continue

        queue_records.append(
            {
                "clinic_name": clinic_name,
                "patient_id": session_row["patient_id"],
                "arrival_time": arrival_time,
                "priority": priority,
                "est_duration": get_duration(priority),
                "chat_session_id": session_id,
                "seen_by_doctor_time": None,
            }
        )

    return queue_records


def sync_clinic_queue_chat_sessions(cur, dry_run: bool) -> None:
    queue_records = _queue_records_from_payload(cur)
    if not queue_records:
        print("[SKIP] public.clinic_queue: 0 rows")
        return

    if dry_run:
        print(f"[DRY_RUN] public.clinic_queue: would sync {len(queue_records)} rows")
        return

    update_sql = """
    UPDATE public.clinic_queue AS queue
    SET chat_session_id = %(chat_session_id)s,
      seen_by_doctor_time = NULL
    WHERE queue.record_id = (
        SELECT record_id
        FROM public.clinic_queue
        WHERE patient_id = %(patient_id)s
          AND clinic_name = %(clinic_name)s
          AND chat_session_id IS NULL
        ORDER BY ABS(EXTRACT(EPOCH FROM (arrival_time - %(arrival_time)s::timestamp))) ASC, record_id ASC
        LIMIT 1
    )
    """

    reset_existing_sql = """
    UPDATE public.clinic_queue
    SET seen_by_doctor_time = NULL
    WHERE patient_id = %(patient_id)s
      AND chat_session_id = %(chat_session_id)s
    """

    insert_sql = """
    INSERT INTO public.clinic_queue (
        clinic_name,
        patient_id,
        arrival_time,
        priority,
        est_duration,
        chat_session_id,
        seen_by_doctor_time
    )
    SELECT
        %(clinic_name)s,
        %(patient_id)s,
        %(arrival_time)s,
        %(priority)s,
        %(est_duration)s,
        %(chat_session_id)s,
        %(seen_by_doctor_time)s
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.clinic_queue
        WHERE patient_id = %(patient_id)s
          AND chat_session_id = %(chat_session_id)s
    )
    """

    updated = 0
    inserted = 0
    reset = 0
    for record in queue_records:
        cur.execute(update_sql, record)
        updated += cur.rowcount
        cur.execute(insert_sql, record)
        inserted += cur.rowcount
        cur.execute(reset_existing_sql, record)
        reset += cur.rowcount

    print(
        f"[UPSERT] public.clinic_queue: synced {len(queue_records)} rows "
        f"(updated {updated}, inserted {inserted}, normalized {reset})"
    )


